+                assertThat(exception.getSuppressed()[0], instanceOf(ElasticsearchException.class));
+                assertEquals(
+                    "simulated",
+                    expectThrows(ElasticsearchException.class, () -> future1.actionGet(10, TimeUnit.SECONDS)).getMessage()
+                );
+            }
+        } finally {
+            barrier.reset();
+            terminate(executorService);
+        }
