+    public void testErrorStoreIsClearedOnBackingIndexBecomingUnmanaged() {
+        String dataStreamName = randomAlphaOfLength(10).toLowerCase(Locale.ROOT);
+        int numBackingIndices = 3;
+        Metadata.Builder builder = Metadata.builder();
